def _get_file_internal(self, fp, headers=None, cb=None, num_cb=10,
             torrent=False, version_id=None, override_num_retries=None,
             response_headers=None, hash_algs=None, query_args=None):
    if headers is None:
        headers = {}
    save_debug = self.bucket.connection.debug
    if self.bucket.connection.debug == 1:
        self.bucket.connection.debug = 0

    query_args = query_args or []
    if torrent:
        query_args.append('torrent')

    if hash_algs is None and not torrent:
        hash_algs = {'md5': md5}
    digesters = dict((alg, hash_algs[alg]()) for alg in hash_algs or {})

    # If a version_id is passed in, use that.  If not, check to see
    # if the Key object has an explicit version_id and, if so, use that.
    # Otherwise, don't pass a version_id query param.
    if version_id is None:
        version_id = self.version_id
    if version_id:
        query_args.append('versionId=%s' % version_id)
    if response_headers:
        for key in response_headers:
            query_args.append('%s=%s' % (
                key, urllib.parse.quote(response_headers[key])))
    query_args = '&'.join(query_args)
    self.open('r', headers, query_args=query_args,
              override_num_retries=override_num_retries)

    data_len = 0
    if cb:
        if self.size is None:
            cb_size = 0
        else:
            cb_size = self.size
        if self.size is None and num_cb != -1:
            # If size is not available due to chunked transfer for example,
            # we'll call the cb for every 1MB of data transferred.
            cb_count = (1024 * 1024) / self.BufferSize
        elif num_cb > 1:
            cb_count = int(math.ceil(cb_size/self.BufferSize/(num_cb-1.0)))
        elif num_cb < 0:
            cb_count = -1
        else:
            cb_count = 0
        i = 0
        cb(data_len, cb_size)
    try:
        for bytes in self:
            fp.write(bytes)
            data_len += len(bytes)
            for alg in digesters:
                digesters[alg].update(bytes)
            if cb:
                if cb_size > 0 and data_len >= cb_size:
                    break
                i += 1
                if i == cb_count or cb_count == -1:
                    cb(data_len, cb_size)
                    i = 0
    except IOError as e:
        if e.errno == errno.ENOSPC:
            raise StorageDataError('Out of space for destination file '
                                   '%s' % fp.name)
        raise
    if cb and (cb_count <= 1 or i > 0) and data_len > 0:
        cb(data_len, cb_size)
    for alg in digesters:
        self.local_hashes[alg] = digesters[alg].digest()
    if self.size is None and not torrent and "Range" not in headers:
        self.size = data_len
    self.close()
    self.bucket.connection.debug = save_debug

def compute_hash(fp, buf_size=8192, size=None, hash_algorithm=md5):
    hash_obj = hash_algorithm()
    spos = fp.tell()
    if size and size < buf_size:
        s = fp.read(size)
    else:
        s = fp.read(buf_size)
    while s:
        if not isinstance(s, bytes):
            s = s.encode('utf-8')
        hash_obj.update(s)
        if size:
            size -= len(s)
            if size <= 0:
                break
        if size and size < buf_size:
            s = fp.read(size)
        else:
            s = fp.read(buf_size)
    hex_digest = hash_obj.hexdigest()
    base64_digest = encodebytes(hash_obj.digest()).decode('utf-8')
    if base64_digest[-1] == '\n':
        base64_digest = base64_digest[0:-1]
    # data_size based on bytes read.
    data_size = fp.tell() - spos
    fp.seek(spos)
    return (hex_digest, base64_digest, data_size)

class PleaseRetryException(Exception):
    """
    Indicates a request should be retried.
    """
    def __init__(self, message, response=None):
        self.message = message
        self.response = response

    def __repr__(self):
        return 'PleaseRetryException("%s", %s)' % (
            self.message,
            self.response
        )

class ResumableDownloadException(Exception):
    """
    Exception raised for various resumable download problems.

    self.disposition is of type ResumableTransferDisposition.
    """

    def __init__(self, message, disposition):
        super(ResumableDownloadException, self).__init__(message, disposition)
        self.message = message
        self.disposition = disposition

    def __repr__(self):
        return 'ResumableDownloadException("%s", %s)' % (
            self.message, self.disposition)

def generate_url(self, expires_in, method, bucket='', key='', headers=None,
                 query_auth=True, force_http=False, response_headers=None,
                 expires_in_absolute=False, version_id=None):
    if self._auth_handler.capability[0] == 'hmac-v4-s3' and query_auth:
        # Handle the special sigv4 case
        return self.generate_url_sigv4(expires_in, method, bucket=bucket,
            key=key, headers=headers, force_http=force_http,
            response_headers=response_headers, version_id=version_id)

    headers = headers or {}
    if expires_in_absolute:
        expires = int(expires_in)
    else:
        expires = int(time.time() + expires_in)
    auth_path = self.calling_format.build_auth_path(bucket, key)
    auth_path = self.get_path(auth_path)
    # optional version_id and response_headers need to be added to
    # the query param list.
    extra_qp = []
    if version_id is not None:
        extra_qp.append("versionId=%s" % version_id)
    if response_headers:
        for k, v in response_headers.items():
            extra_qp.append("%s=%s" % (k, urllib.parse.quote(v)))
    if self.provider.security_token:
        headers['x-amz-security-token'] = self.provider.security_token
    if extra_qp:
        delimiter = '?' if '?' not in auth_path else '&'
        auth_path += delimiter + '&'.join(extra_qp)
    self.calling_format.build_path_base(bucket, key)
    if query_auth and not self.anon:
        c_string = boto.utils.canonical_string(method, auth_path, headers,
                                               expires, self.provider)
        b64_hmac = self._auth_handler.sign_string(c_string)
        encoded_canonical = urllib.parse.quote(b64_hmac, safe='')
        query_part = '?' + self.QueryString % (encoded_canonical, expires,
                                               self.aws_access_key_id)
    else:
        query_part = ''
    if headers:
        hdr_prefix = self.provider.header_prefix
        for k, v in headers.items():
            if k.startswith(hdr_prefix):
                # headers used for sig generation must be
                # included in the url also.
                extra_qp.append("%s=%s" % (k, urllib.parse.quote(v)))
    if extra_qp:
        delimiter = '?' if not query_part else '&'
        query_part += delimiter + '&'.join(extra_qp)
    if force_http:
        protocol = 'http'
        port = 80
    else:
        protocol = self.protocol
        port = self.port
    return self.calling_format.build_url_base(self, protocol,
                                              self.server_name(port),
                                              bucket, key) + query_part
